begin;
create table if not exists public.billing_customers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,customer_id uuid references public.customers(id) on delete set null,legal_name text not null,tax_id text,billing_email text,address text,postal_code text,city text,country text not null default 'ES',payment_terms_days integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(company_id,tax_id));
create table if not exists public.invoice_series(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid references public.restaurants(id) on delete cascade,name text not null,prefix text not null,next_number integer not null default 1,document_type text not null default 'invoice' check(document_type in('invoice','credit_note','simplified')),active boolean not null default true,unique(company_id,prefix));
create table if not exists public.sales_invoices(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,billing_customer_id uuid references public.billing_customers(id) on delete set null,series_id uuid references public.invoice_series(id) on delete set null,invoice_number text not null,issue_date date not null default current_date,due_date date,currency text not null default 'EUR',status text not null default 'draft' check(status in('draft','issued','partially_paid','paid','overdue','cancelled')),subtotal numeric(12,2) not null default 0,tax_amount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,paid_amount numeric(12,2) not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,invoice_number));
create table if not exists public.sales_invoice_lines(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.sales_invoices(id) on delete cascade,description text not null,quantity numeric(12,3) not null default 1,unit_price numeric(12,4) not null default 0,discount_percent numeric(5,2) not null default 0,tax_rate numeric(5,2) not null default 21,line_subtotal numeric(12,2) not null default 0,line_tax numeric(12,2) not null default 0,line_total numeric(12,2) not null default 0,sort_order integer not null default 0);
create table if not exists public.invoice_payments(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,invoice_id uuid not null references public.sales_invoices(id) on delete cascade,payment_method_id uuid references public.payment_methods(id) on delete set null,payment_date date not null default current_date,amount numeric(12,2) not null check(amount>0),reference text,notes text,created_at timestamptz not null default now());
create index if not exists billing_customers_company_idx on public.billing_customers(company_id,active);create index if not exists sales_invoices_status_idx on public.sales_invoices(restaurant_id,status,due_date);create index if not exists invoice_payments_invoice_idx on public.invoice_payments(invoice_id,payment_date desc);
alter table public.billing_customers enable row level security;alter table public.invoice_series enable row level security;alter table public.sales_invoices enable row level security;alter table public.sales_invoice_lines enable row level security;alter table public.invoice_payments enable row level security;
do $$ declare t text;begin foreach t in array array['billing_customers','invoice_series','sales_invoices','invoice_payments'] loop execute format('drop policy if exists company_members_access on public.%I',t);execute format('create policy company_members_access on public.%I for all to authenticated using(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid()))',t,t,t);end loop;end $$;
drop policy if exists sales_invoice_lines_access on public.sales_invoice_lines;create policy sales_invoice_lines_access on public.sales_invoice_lines for all to authenticated using(exists(select 1 from public.sales_invoices i join public.company_members cm on cm.company_id=i.company_id where i.id=invoice_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.sales_invoices i join public.company_members cm on cm.company_id=i.company_id where i.id=invoice_id and cm.user_id=auth.uid()));
grant select,insert,update,delete on public.billing_customers,public.invoice_series,public.sales_invoices,public.sales_invoice_lines,public.invoice_payments to authenticated;
do $$ declare c uuid;r uuid;bc uuid;ser uuid;inv uuid;begin select id into c from public.companies order by created_at limit 1;select id into r from public.restaurants where company_id=c order by created_at limit 1;if c is not null and r is not null then insert into public.billing_customers(company_id,legal_name,tax_id,billing_email,address,postal_code,city,payment_terms_days) values(c,'Eventos Valencia SL','B12345678','facturacion@eventosvalencia.example','Calle Colón 10','46004','Valencia',30) on conflict(company_id,tax_id) do update set billing_email=excluded.billing_email returning id into bc;insert into public.invoice_series(company_id,restaurant_id,name,prefix,next_number) values(c,r,'Serie general','FAC-2026-',2) on conflict(company_id,prefix) do update set name=excluded.name returning id into ser;insert into public.sales_invoices(company_id,restaurant_id,billing_customer_id,series_id,invoice_number,issue_date,due_date,status,subtotal,tax_amount,total,paid_amount,notes) values(c,r,bc,ser,'FAC-2026-0001',current_date,current_date+30,'issued',850,178.50,1028.50,0,'Evento de empresa') on conflict(company_id,invoice_number) do update set total=excluded.total returning id into inv;insert into public.sales_invoice_lines(invoice_id,description,quantity,unit_price,tax_rate,line_subtotal,line_tax,line_total) select inv,'Menú evento corporativo',50,17,21,850,178.50,1028.50 where not exists(select 1 from public.sales_invoice_lines where invoice_id=inv);end if;end $$;
commit;
